<?php require __DIR__.'/../includes/bootstrap.php';require_member();$pageTitle='My fines';$basePath='../';$s=$pdo->prepare('SELECT id FROM members WHERE user_id=?');$s->execute([current_user()['id']]);$mid=$s->fetchColumn();$s=$pdo->prepare('SELECT f.*,b.title FROM fines f JOIN books b ON b.id=f.book_id WHERE f.member_id=? ORDER BY f.id DESC');$s->execute([$mid]);$rows=$s->fetchAll();$s=$pdo->prepare('SELECT l.id,l.due_date,b.title FROM loans l JOIN books b ON b.id=l.book_id WHERE l.member_id=? AND l.status="issued" AND l.due_date<CURDATE()');$s->execute([$mid]);$est=$s->fetchAll();require __DIR__.'/../includes/layout_top.php';?><div class="panel"><h3>Recorded fines</h3><p class="muted">Final fines are calculated by the administrator when a book is returned. Payments and waivers are recorded by the administrator.</p><div class="table-wrap"><table><thead><tr><th>Book</th><th>Amount</th><th>Status</th><th>Note</th></tr></thead><tbody><?php foreach($rows as $f):?><tr><td><?=e($f['title'])?></td><td><?=money($f['amount'])?></td><td><span class="pill <?=$f['status']==='unpaid'?'danger':'success'?>"><?=$f['status']?></span></td><td><?=e($f['note']??'—')?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="4" class="empty">No final fines have been recorded.</td></tr><?php endif;?></tbody></table></div></div><div class="panel"><h3>Current overdue estimates</h3><p class="muted">These estimates can change until the book is returned.</p><?php if(!$est):?><p class="empty">No currently overdue books.</p><?php else:?><div class="table-wrap"><table><thead><tr><th>Book</th><th>Due date</th><th>Overdue days</th><th>Estimated fine</th></tr></thead><tbody><?php foreach($est as $x):$d=overdue_days($x['due_date']);?><tr><td><?=e($x['title'])?></td><td><?=e($x['due_date'])?></td><td><?=$d?></td><td><?=money($d*(float)setting($pdo,'fine_per_day',10))?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></div><?php require __DIR__.'/../includes/layout_bottom.php';?>
